import {simulateCatch} from './gravity-physics.js';
import * as T from './assets/three.module.js';
import {simulateDrop,sampleDrop} from './lab-physics.js';
import {sceneNavigation} from './scene-navigation.js';
const $=s=>document.querySelector(s),fmt=(n,d=2)=>n.toLocaleString('en-US',{maximumFractionDigits:d});
export function setupGravityStudio(api,gfx){
 const original=$('.gravity-lab'),section=document.createElement('section');section.id='gravity-studio';section.className='wrap dynamics-section';
 section.innerHTML='<div class="section-heading"><div><span class="eyebrow">EXPERIMENTAL DYNAMICS / THREE-WORLD BENCH</span><h2>GRAVITY <em>DYNAMICS.</em></h2></div><p>One release. Three gravitational environments.<br>Measure the difference, frame by frame.</p></div><div class="gravity-presets"><button data-gravity-preset="vacuum">Vacuum comparison</button><button data-gravity-preset="drag">Drag chamber</button><button data-gravity-preset="bounce">Elastic impacts</button><button data-gravity-preset="launch">Vertical launch</button><button id="gravity-synchronized">Synchronized landing</button></div><div class="gravity-deck"><div class="gravity-visual"><div id="gravity-render" tabindex="0" role="img" aria-label="Three-ball gravity bench. Drag to orbit; drag a ball before release to set the height."></div><div id="gravity-phase" role="status">READY / CONTROLLED RELEASE</div><div id="gravity-lanes"></div><div class="scene-actions"><button id="gravity-release" class="primary">Release all three ↓</button><button id="gravity-pause">Pause</button><button id="gravity-step">Step 1/60 s</button><button id="gravity-reset">Reset</button><button id="gravity-camera">Reset camera</button><button id="gravity-export">Export CSV</button></div><div class="gravity-transport"><label>Simulation time<input id="gravity-timeline" type="range" min="0" max="20" step=".0166667" value="0"></label><output id="gravity-clock">0.000 s</output><label>Playback<select id="gravity-rate"><option value=".1">0.1×</option><option value=".25">0.25×</option><option value=".5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option></select></label></div><div class="gravity-charts"><div><span>HEIGHT / m</span><svg id="gravity-height-chart" viewBox="0 0 600 130" role="img" aria-label="Height versus time for three worlds"></svg></div><div><span>VELOCITY / m/s · UP IS POSITIVE</span><svg id="gravity-speed-chart" viewBox="0 0 600 130" role="img" aria-label="Vertical velocity versus time for three worlds"></svg></div></div></div><div id="gravity-settings" class="workspace-config"></div></div><p class="source-note">Three identical spherical test masses, constant local g, vertical motion. Geometry is normalized; the view rescales after height changes. Optional quadratic drag uses the same selected chamber density on all worlds, not each planet’s atmosphere. Choose a rigid restitution plane or a spring-damper center contact. The net membrane follows the coupled center displacement with pinned edges and illustrative ripples; it is not a full cloth solver. Net deformation is visually compressed. Height is measured from the undeformed net; negative height is net sag. Plots and CSV use a 240 Hz numerical integration sampled at 60 Hz; changing inputs resets the experiment.</p>';
 $('#field-lab').before(section);const jump=document.createElement('a');jump.href='#gravity-studio';jump.textContent='Gravity lab';document.querySelector('.header nav').append(jump);const settings=$('#gravity-settings');original.classList.add('gravity-console');settings.append(original);original.querySelector('.instrument-title').innerHTML='<span>01 / TEST MASS & PRIMARY WORLD</span>';original.querySelector('.gravity-graphic').remove();
 const opts=api.planets.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('');const range=(id,label,min,max,step,value)=>`<label>${label}<input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;
 const extra=document.createElement('div');extra.className='gravity-parameters';extra.innerHTML=`${range('drop-height','Release height / m',1,200,1,30)}<div class="pair"><label>Reference A<select id="gravity-reference-a">${opts}</select></label><label>Reference B<select id="gravity-reference-b">${opts}</select></label></div><label>Chamber medium<select id="gravity-medium"><option value="0">Vacuum / 0 kg/m³</option><option value="1.225">Air chamber / 1.225 kg/m³</option><option value="5">Dense chamber / 5 kg/m³</option></select></label>${range('gravity-radius','Sphere aerodynamic radius / m',.05,1,.01,.2)}${range('gravity-launch','Initial velocity / m/s · up positive',-20,30,.5,0)}${range('gravity-bounce','Impact restitution / 0–1',0,.9,.05,0)}<label class="check-label"><input id="gravity-ghosts" type="checkbox" checked> Trajectory markers</label><label class="check-label"><input id="gravity-net" type="checkbox" checked> Net & measurement grid</label><div id="gravity-readings" class="workspace-readout" aria-live="polite"></div>`;settings.append(extra);const netControls=document.createElement('div');netControls.className='gravity-net-controls';netControls.innerHTML='<span class="eyebrow">CONTACT LAB / DEFORMABLE CATCH NET</span><label>Contact model<select id="gravity-contact"><option value="net">Spring-damper net</option><option value="rigid">Rigid impact / restitution</option></select></label><label>Net stiffness / N m⁻¹<input id="gravity-stiffness" type="range" min="1000" max="60000" step="1000" value="12000"></label><label>Net damping / kg s⁻¹<input id="gravity-damping" type="range" min="0" max="4000" step="50" value="900"></label><label><input id="gravity-sync" type="checkbox"> Match first-contact times / vacuum</label><output id="gravity-net-state"></output>';extra.append(netControls);$('#gravity-reference-a').value=3;$('#gravity-reference-b').value=4;$('#gravity-planet').value=api.getState().current;
 let chartDuration=20;let scene,camera,renderer,nav,visible=false,running=false,t=0,last=0,paintClock=0,traces=[],worlds=[],balls=[],nets=[],ghosts=[],netMeshes=[],failed=false,plotSpan=1;const colors=[0xd9b57d,0xa1c1b5,0x97aaca],cssColors=['#d9b57d','#a1c1b5','#97aaca'];const root=$('#gravity-render');
 try{renderer=gfx.rendererFor(root);scene=new T.Scene();scene.background=new T.Color(0x080b0e);camera=new T.PerspectiveCamera(38,1,.01,250);gfx.observeSize(root,renderer,camera);gfx.addLights(scene);scene.add(new T.AmbientLight(0xc9c7bb,.5));nav=sceneNavigation(root,camera,{distance:23,pitch:.22,yaw:.18,targetY:4.5});
 const bench=new T.Mesh(new T.BoxGeometry(11,.12,4),new T.MeshStandardMaterial({color:0x191e21,roughness:.6,metalness:.55}));bench.position.y=-.18;scene.add(bench);for(let i=0;i<3;i++){const x=(i-1)*3.25,ball=new T.Mesh(new T.SphereGeometry(.25,40,28),new T.MeshPhysicalMaterial({color:colors[i],metalness:.7,roughness:.22,clearcoat:.7}));ball.userData.lane=i;balls.push(ball);scene.add(ball);
 const grid=new T.Group(),floor=new T.Mesh(new T.PlaneGeometry(2.6,3,30,30),new T.MeshBasicMaterial({color:colors[i],wireframe:true,transparent:true,opacity:.5,side:T.DoubleSide}));floor.rotation.x=-Math.PI/2;floor.position.set(x,2.2,0);grid.add(floor);netMeshes.push(floor);const metal=new T.MeshStandardMaterial({color:0x56616a,metalness:.7,roughness:.25});for(const z of [-1.5,1.5]){const bar=new T.Mesh(new T.CylinderGeometry(.035,.035,2.8,12),metal);bar.rotation.z=Math.PI/2;bar.position.set(x,2.2,z);grid.add(bar);}for(const side of [-1,1])for(const z of [-1.5,1.5]){const post=new T.Mesh(new T.CylinderGeometry(.045,.055,2.2,12),metal);post.position.set(x+side*1.35,1.1,z);grid.add(post);}const back=new T.Mesh(new T.PlaneGeometry(2.6,6.5,10,20),new T.MeshBasicMaterial({color:colors[i],wireframe:true,transparent:true,opacity:.16,side:T.DoubleSide}));back.position.set(x,5.4,-1.6);grid.add(back);nets.push(grid);scene.add(grid);const markers=new T.Group();for(let j=0;j<24;j++){const dot=new T.Mesh(new T.SphereGeometry(.035,6,4),new T.MeshBasicMaterial({color:colors[i],transparent:true,opacity:.5}));markers.add(dot)}ghosts.push(markers);scene.add(markers);}}
 catch(e){failed=true;root.classList.add('graphics-unavailable');root.innerHTML='<p class="fallback-message">3D unavailable. Timeline, physics, plots, presets, and export remain available.</p>';}
 function inputs(){return {height:+$('#drop-height').value,mass:+$('#body-mass').value,radius:+$('#gravity-radius').value,density:+$('#gravity-medium').value,launch:+$('#gravity-launch').value,restitution:+$('#gravity-bounce').value,duration:20,stiffness:+$('#gravity-stiffness').value,damping:+$('#gravity-damping').value};}
 function rebuild(){running=false;t=0;const p=inputs();worlds=[$('#gravity-planet').value,$('#gravity-reference-a').value,$('#gravity-reference-b').value].map(x=>api.planets[+x]);traces=worlds.map(w=>{const height=$('#gravity-sync').checked?p.height*w.gravity/worlds[0].gravity:p.height;const model=$('#gravity-contact').value==='net'?simulateCatch:simulateDrop;return {...model({...p,height,g:w.gravity}),releaseHeight:height};});plotSpan=Math.max(p.height,...traces.flatMap(tr=>tr.samples.map(s=>s.y)))*1.03;chartDuration=p.restitution>0?20:Math.min(20,Math.max(5,...traces.map(tr=>(tr.impacts[0]?.t||20)*1.3)));$('#gravity-timeline').max=chartDuration;$('#gravity-lanes').innerHTML=worlds.map((w,i)=>`<div style="color:${cssColors[i]}"><span>0${i+1} / ${w.name.toUpperCase()}</span><strong>${w.gravity} m/s²</strong></div>`).join('');$('#gravity-phase').textContent='READY / CONTROLLED RELEASE';$('#gravity-pause').textContent='Pause';drawCharts();update();}
 function update(paint=true){const p=inputs(),states=traces.map(trace=>sampleDrop(trace.samples,t)),span=plotSpan;states.forEach((s,i)=>{const impact=traces[i].impacts[0],contact=$('#gravity-contact').value==='net'&&impact&&s.y<0,sag=contact?(s.sag||0):0,visualSag=sag/(1+sag)*1.8;if(balls[i]){balls[i].position.set((i-1)*3.25,2.45+(contact?-visualSag:s.y/span*6.5),0);const pulse=impact?Math.exp(-Math.abs(t-impact.t)*8):0;balls[i].material.emissive.setHex(colors[i]);balls[i].material.emissiveIntensity=pulse*.4;balls[i].scale.set(1+pulse*.06,1-pulse*.10,1+pulse*.06);}if(netMeshes[i]){const a=netMeshes[i].geometry.attributes.position,age=impact?Math.max(0,t-impact.t):0;for(let j=0;j<a.count;j++){const x=a.getX(j),z=a.getZ(j),r=Math.hypot(x,z),edge=Math.max(0,1-Math.pow(Math.abs(x)/1.3,4))*Math.max(0,1-Math.pow(Math.abs(z)/1.5,4)),wave=contact?Math.sin(r*9-age*15)*Math.exp(-age*2)*.035:0;a.setY(j,edge*(-visualSag*Math.exp(-r*r*1.5)+wave));}a.needsUpdate=true;}if(ghosts[i]){ghosts[i].visible=$('#gravity-ghosts').checked;ghosts[i].children.forEach((dot,j)=>{const q=sampleDrop(traces[i].samples,Math.max(0,t-j*.1));dot.position.set((i-1)*3.25,2.45+Math.max(0,q.y)/span*6.5,0);dot.visible=t>j*.1;});}if(nets[i])nets[i].visible=$('#gravity-net').checked;});
 if(!paint)return;$('#gravity-net-state').textContent=$('#gravity-contact').value==='net'?'Elastic catch / stiffness '+p.stiffness.toLocaleString()+' N/m · damping '+p.damping+' kg/s':'Rigid floor / restitution '+p.restitution;$('#gravity-readings').innerHTML=states.map((s,i)=>`<div style="border-left:2px solid ${cssColors[i]};padding-left:10px"><span>${worlds[i].name.toUpperCase()} / FIRST CONTACT ${traces[i].impacts[0]?traces[i].impacts[0].t.toFixed(3)+' s':'BEYOND 20 s'}</span><strong>${fmt(s.y)} m · ${fmt(s.v)} m/s</strong><small>KE ${fmt(.5*p.mass*s.v*s.v)} J · PE ${fmt(p.mass*worlds[i].gravity*s.y)} J · spring ${fmt(s.spring||0)} J</small></div>`).join('');$('#gravity-clock').textContent=t.toFixed(3)+' s';$('#gravity-timeline').value=t;for(const id of ['gravity-height-chart','gravity-speed-chart']){const cursor=$('#'+id+' .plot-cursor');if(cursor){cursor.setAttribute('x1',t/chartDuration*600);cursor.setAttribute('x2',t/chartDuration*600);}}}
 function drawCharts(){for(const [id,key] of [['gravity-height-chart','y'],['gravity-speed-chart','v']]){const values=traces.flatMap(tr=>tr.samples.map(s=>s[key])),min=Math.min(0,...values),max=Math.max(1,...values),scale=v=>120-(v-min)/(max-min)*110;$('#'+id).innerHTML=`<path d="M0 10H600M0 65H600M0 120H600" fill="none" stroke="#2e3539" stroke-width="1"/>`+traces.map((tr,i)=>`<path d="${tr.samples.filter((s,j)=>j%6===0&&s.t<=chartDuration).map((s,j)=>(j?'L':'M')+(s.t/chartDuration*600).toFixed(1)+' '+scale(s[key]).toFixed(1)).join(' ')}" fill="none" stroke="${cssColors[i]}" stroke-width="2"/>`).join('')+'<line class="plot-cursor" x1="0" x2="0" y1="0" y2="130" stroke="#fff" stroke-width="1"/>';}}
 $('#gravity-release').onclick=()=>{t=0;running=api.getState().motion;$('#gravity-phase').textContent=running?'RELEASE / THREE SYNCHRONIZED CLOCKS':'STATIC MODE / SCRUB TIMELINE TO COMPARE';if(!running)t=Math.min(20,Math.max(...traces.map(tr=>tr.impacts[0]?.t||0)));update();};$('#gravity-pause').onclick=e=>{running=!running&&api.getState().motion;e.target.textContent=running?'Pause':'Resume';};$('#gravity-reset').onclick=rebuild;$('#gravity-step').onclick=()=>{running=false;t=Math.min(chartDuration,t+1/60);update()};$('#gravity-camera').onclick=()=>nav?.reset();$('#gravity-timeline').oninput=e=>{running=false;t=+e.target.value;update()};$('#gravity-rate').onchange=()=>{};
 for(const id of ['drop-height','body-mass','gravity-planet','gravity-reference-a','gravity-reference-b','gravity-medium','gravity-radius','gravity-launch','gravity-bounce','gravity-stiffness','gravity-damping','gravity-contact','gravity-sync'])$('#'+id).addEventListener('input',rebuild);for(const id of ['gravity-net','gravity-ghosts'])$('#'+id).onchange=update;
 document.querySelectorAll('[data-gravity-preset]').forEach(b=>b.onclick=()=>{$('#gravity-medium').value=b.dataset.gravityPreset==='drag'?'1.225':'0';$('#gravity-contact').value=b.dataset.gravityPreset==='bounce'?'rigid':'net';$('#gravity-sync').checked=false;$('#gravity-bounce').value=b.dataset.gravityPreset==='bounce'?.75:0;$('#gravity-launch').value=b.dataset.gravityPreset==='launch'?20:0;$('#body-mass').value=b.dataset.gravityPreset==='drag'?10:75;$('#gravity-radius').value=b.dataset.gravityPreset==='drag'?.8:.2;$('#body-mass').dispatchEvent(new Event('input'));rebuild();});
 document.addEventListener('planet-change',()=>{$('#gravity-planet').value=api.getState().current;$('#gravity-planet').dispatchEvent(new Event('change'));rebuild()});
 $('#gravity-synchronized').onclick=()=>{$('#gravity-sync').checked=true;$('#gravity-medium').value='0';$('#gravity-launch').value=0;rebuild()};$('#gravity-sync').addEventListener('change',()=>{if($('#gravity-sync').checked){$('#gravity-medium').value='0';$('#gravity-launch').value=0;}rebuild()});
 $('#gravity-export').onclick=()=>{const p=inputs(),rows=['world,time_s,height_m,velocity_m_s,kinetic_J,potential_J,mass_kg,radius_m,density_kg_m3,g_m_s2,restitution,initial_velocity_m_s,release_height_m,net_sag_m,spring_J,contact_model'];traces.forEach((tr,i)=>tr.samples.forEach(s=>rows.push([worlds[i].name,s.t,s.y,s.v,.5*p.mass*s.v*s.v,p.mass*worlds[i].gravity*s.y,p.mass,p.radius,p.density,worlds[i].gravity,p.restitution,p.launch,tr.releaseHeight,s.sag||0,s.spring||0,$('#gravity-contact').value].join(','))));const u=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='orbit-gravity-experiment.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)};
 if(renderer){const ray=new T.Raycaster(),mouse=new T.Vector2(),plane=new T.Plane(new T.Vector3(0,0,1),0);let drag=false,dragSpan=100;root.addEventListener('pointerdown',e=>{if(running)return;const r=root.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);drag=ray.intersectObjects(balls).length>0;if(drag){dragSpan=Math.max(inputs().height,...traces.flatMap(tr=>tr.samples.map(s=>s.y)))*1.03;root.setPointerCapture(e.pointerId);e.stopImmediatePropagation()}},true);root.addEventListener('pointermove',e=>{if(!drag)return;const r=root.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);const hit=ray.ray.intersectPlane(plane,new T.Vector3());if(hit){$('#drop-height').value=Math.max(1,Math.min(200,Math.round((hit.y-2.45)/6.5*dragSpan)));rebuild();balls.forEach(ball=>ball.position.y=Math.max(2.45,hit.y));}e.stopImmediatePropagation()},true);['pointerup','pointercancel'].forEach(ev=>root.addEventListener(ev,()=>{drag=false;update()}));renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();failed=true;root.classList.add('graphics-unavailable');root.innerHTML='<p class="fallback-message">3D context lost. Numerical tools and export remain active.</p>'})}
 new IntersectionObserver(e=>visible=e[0].isIntersecting).observe(section);function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.1)||0;last=now;if(!visible||document.hidden)return;if(running&&api.getState().motion){t=Math.min(chartDuration,t+dt*+$('#gravity-rate').value);paintClock+=dt;if(paintClock>.05){paintClock=0;update()}else update(false);if(t>=chartDuration){running=false;$('#gravity-phase').textContent='RUN COMPLETE / SCRUB TO REPLAY';update()}}if(!failed&&renderer){nav.update(dt,api.getState().motion);renderer.render(scene,camera)}}rebuild();if(location.hash==='#gravity-studio')section.scrollIntoView();requestAnimationFrame(frame);
}
